42	/* One round costs about two minutes on this board, so asking again on every
43	 * alarm-set change would just queue behind the answer already in flight. */
44	
45	#define VG_ADV_MIN_GAP_MS  20000u    /* between two rounds */
46	#define VG_ADV_REFRESH_MS  300000u   /* re-ask for a long-running alarm set */
47	#define VG_ADV_RETRY_MS    300000u   /* after a round that produced no usable
48	                                      * document: the same alarm set must not
49	                                      * buy a fresh LLM round every 20 s, an
50	                                      * alarm set that changed still may.
51	                                      * A round takes about 195 s, so a short
52	                                      * retry would keep this single channel
53	                                      * busy almost continuously and starve
54	                                      * the daily report. */
