62	static vg_ai_advice_doc_t g_doc;
63	static bool               g_loaded;
64	static vg_ui_advice_state_t g_state = VG_UI_ADV_IDLE;
65	static char               g_sig[VG_ADV_SIG_MAX];
66	static uint32_t           g_boot;
67	static uint32_t           g_req;
68	static uint32_t           g_last_ask_ms;
69	static uint32_t           g_last_ok_ms;
70	static uint32_t           g_next_ask_ms;
71	static bool               g_asked_once;
