116	
117	      snprintf(snap[i].id, sizeof(snap[i].id), "%s", list[i].sensor_id);
118	      strncpy(snap[i].name, nm, sizeof(snap[i].name) - 1);
119	      snap[i].name[sizeof(snap[i].name) - 1] = '\0';
120	      snap[i].epoch = (s != NULL) ? s->al_epoch : 0;
121	      snap[i].sev = (list[i].severity == VG_SEV_CRIT)   ? VG_AI_SEV_CRIT
122	                  : (list[i].severity == VG_SEV_OFFLINE) ? VG_AI_SEV_OFFLINE
123	                                                         : VG_AI_SEV_WARN;
124	      snap[i].value = list[i].value;
125	      snap[i].threshold = list[i].threshold;
