143	/* Only has to differ between boots; the epoch inside the document then
144	 * separates alarm episodes within one boot. */
145	
146	static uint32_t advice_boot_nonce(void)
147	{
148	  uint32_t n;
149	
150	  if (g_boot != 0)
151	    {
152	      return g_boot;
153	    }
154	
155	  n = (uint32_t)time(NULL) ^ vg_agent_round_now_ms() ^ 0x5a17c0deu;
156	  if (n == 0)
157	    {
158	      n = 0x5a17c0deu;
159	    }
160	
161	  g_boot = n;
162	  return n;
163	}
164	
165	static void build_sig(char *out, size_t cap, const vg_advice_alarm_t *list,
166	                      int n)
167	{
168	  size_t used = 0;
169	  int i;
170	
171	  out[0] = '\0';
172	
173	  for (i = 0; i < n; i++)
174	    {
175	      int w;
176	
177	      w = snprintf(out + used, cap - used, "%s:%u:%d,",
178	                   list[i].id, (unsigned)list[i].epoch, (int)list[i].sev);
179	      if (w < 0 || (size_t)w >= cap - used)
180	        {
181	          break;
182	        }
183	
184	      used += (size_t)w;
185	    }
186	}
187	
188	/* Read and validate what the agent wrote for the round that just finished. */
189	
190	static void advice_load(void)
191	{
192	  uint32_t boot;
193	  uint32_t req;
194	  int fd;
195	  ssize_t got;
196	  int rc;
197	
198	  fd = open(VG_ADV_FILE, O_RDONLY);
199	  if (fd < 0)
200	    {
201	      syslog(LOG_WARNING, "[%s] no advice file (%d)\n", TAG, errno);
202	      advice_set_state(VG_UI_ADV_ERROR);
203	      return;
204	    }
205	
206	  got = read(fd, s_raw, sizeof(s_raw) - 1);
207	  close(fd);
208	
209	  if (got <= 0)
210	    {
211	      advice_set_state(VG_UI_ADV_ERROR);
212	      return;
213	    }
214	
215	  s_raw[got] = '\0';
216	
217	  pthread_mutex_lock(&g_lock);
218	  boot = g_boot;
219	  req = g_req;
220	  pthread_mutex_unlock(&g_lock);
221	
222	  rc = vg_ai_advice_parse(s_raw, (size_t)got, boot, req, &s_parsed);
223	  if (rc != VG_AI_OK)
224	    {
225	      /* Rejected whole: the page keeps showing the rule summary, and the
226	       * rejection is recorded rather than half-applied. */
227	
228	      syslog(LOG_WARNING, "[%s] advice rejected rc=%d (%d bytes)\n",
229	             TAG, rc, (int)got);
230	      advice_set_state(VG_UI_ADV_ERROR);
231	      return;
232	    }
233	
234	  pthread_mutex_lock(&g_lock);
235	  g_doc = s_parsed;
236	  g_loaded = true;
237	  g_state = VG_UI_ADV_READY;
238	  g_last_ok_ms = vg_agent_round_now_ms();
239	  g_next_ask_ms = 0;
240	  pthread_mutex_unlock(&g_lock);
241	
242	  syslog(LOG_INFO, "[%s] advice loaded: %d entries\n", TAG, s_parsed.n);
243	}
244	
245	static void advice_drop(void)
246	{
247	  pthread_mutex_lock(&g_lock);
248	
249	  if (g_loaded || g_state != VG_UI_ADV_IDLE)
250	    {
251	      g_loaded = false;
252	      g_state = VG_UI_ADV_IDLE;
253	      g_sig[0] = '\0';
254	      g_asked_once = false;
255	      g_next_ask_ms = 0;
256	    }
257	
258	  pthread_mutex_unlock(&g_lock);
259	}
260	
261	void vg_advice_tick(void)
262	{
263	#ifdef CONFIG_EXAMPLES_AI_AGENT_VELA
264	  static char req[VG_ADV_REQ_MAX];
265	  static vg_advice_alarm_t snap[VG_AI_ADV_MAX];
266	  vg_ai_alarm_in_t in[VG_AI_ADV_MAX];
267	  char sig[VG_ADV_SIG_MAX];
268	  uint32_t now = vg_agent_round_now_ms();
269	  enum vg_agent_round_state rnd;
270	  bool changed;
271	  bool refresh;
272	  bool due;
273	  int n;
274	  int i;
275	  int len;
276	  int rc;
277	
278	  pthread_mutex_lock(&g_snap_lock);
279	  memcpy(snap, g_snap, sizeof(snap));
280	  n = g_snap_n;
281	  pthread_mutex_unlock(&g_snap_lock);
282	
283	  if (n <= 0)
284	    {
285	      /* Release our own finished round first: the queue refuses to start a
286	       * new round while any result is still unconsumed. */
287	
288	      if (vg_agent_round_owner() == VG_AGENT_ROUND_OWNER_ADVICE)
289	        {
290	          enum vg_agent_round_state rst = vg_agent_round_state();
291	
292	          if (rst == VG_AGENT_ROUND_DONE || rst == VG_AGENT_ROUND_ERROR)
293	            {
294	              vg_agent_round_clear();
295	            }
296	        }
297	
298	      advice_drop();
299	      return;
300	    }
301	
302	  build_sig(sig, sizeof(sig), snap, n);
303	
304	  /* A round is in flight: nothing to do but wait. */
305	
306	  if (vg_agent_round_busy())
307	    {
308	      advice_set_state(VG_UI_ADV_PENDING);
309	      return;
310	    }
311	
312	  /* A finished round nobody claimed - a manual one whose process went away,
313	   * most likely - would hold the channel forever now that the queue refuses
314	   * to start a round while a terminal state is present. */
315	
316	  vg_agent_round_reclaim(VG_AGENT_ROUND_OWNER_ADVICE,
317	                         VG_AGENT_ROUND_RECLAIM_MS);
318	
319	  /* A round just ended (or failed).  Only a round this flow asked for says
320	   * anything about alarm_advice.txt: the daily flow shares the channel and
321	   * its reply is a different file.  A round owned by the other flow is left
322	   * alone here, and this tick carries on to the asking logic below. */
323	
324	  rnd = vg_agent_round_state();
325	  if ((rnd == VG_AGENT_ROUND_DONE || rnd == VG_AGENT_ROUND_ERROR) &&
326	      vg_agent_round_owner() == VG_AGENT_ROUND_OWNER_ADVICE)
327	    {
328	      if (rnd == VG_AGENT_ROUND_DONE)
329	        {
330	          advice_load();
331	        }
332	      else
333	        {
334	          advice_set_state(VG_UI_ADV_ERROR);
335	        }
336	
337	      /* The round ended without a document the parser accepted.  Hold the
338	       * same alarm set off for a while: a rejected or missing file is not
339	       * going to fix itself in the next 20 s, and each retry costs a full
340	       * LLM round. */
341	
342	      pthread_mutex_lock(&g_lock);
343	      if (!g_loaded)
344	        {
345	          g_next_ask_ms = now + VG_ADV_RETRY_MS;
346	        }
347	      pthread_mutex_unlock(&g_lock);
348	
349	      vg_agent_round_clear();
350	    }
351	
352	  /* Read the gate after the round bookkeeping above, so a backoff armed by
353	   * the round that just ended is already in effect for this tick. */
354	
355	  pthread_mutex_lock(&g_lock);
356	  changed = (strcmp(sig, g_sig) != 0);
357	  refresh = g_loaded && g_last_ok_ms != 0 &&
358	            now - g_last_ok_ms >= VG_ADV_REFRESH_MS;
359	  due = changed || g_next_ask_ms == 0 ||
360	        (int32_t)(now - g_next_ask_ms) >= 0;
361	  pthread_mutex_unlock(&g_lock);
362	
363	  if (!changed && !refresh && g_loaded)
364	    {
365	      return;
366	    }
367	
368	  if (!due)
369	    {
370	      return;
371	    }
372	
373	  if (g_asked_once && now - g_last_ask_ms < VG_ADV_MIN_GAP_MS)
374	    {
375	      return;
376	    }
377	
378	  memset(in, 0, sizeof(in));
379	  for (i = 0; i < n; i++)
380	    {
381	      in[i].id = snap[i].id;
382	      in[i].name = snap[i].name;
383	      in[i].epoch = snap[i].epoch;
384	      in[i].sev = snap[i].sev;
385	      in[i].value = snap[i].value;
386	      in[i].threshold = snap[i].threshold;
387	      in[i].dur_s = snap[i].dur_s;
388	    }
389	
390	  pthread_mutex_lock(&g_lock);
391	  g_req++;
392	  len = vg_ai_advice_build_request(req, sizeof(req), advice_boot_nonce(),
393	                                   g_req, in, n);
394	  if (len > 0)
395	    {
396	      memcpy(g_sig, sig, sizeof(g_sig));
397	      g_sig[sizeof(g_sig) - 1] = '\0';
398	    }
399	  pthread_mutex_unlock(&g_lock);
400	
401	  if (len <= 0)
402	    {
403	      syslog(LOG_WARNING, "[%s] request build failed: %d\n", TAG, len);
404	      advice_set_state(VG_UI_ADV_ERROR);
405	      return;
406	    }
407	
408	  rc = vg_agent_round_queue_owned(req, VG_AGENT_ROUND_OWNER_ADVICE);
409	  if (rc != 0)
410	    {
411	      if (rc != -EBUSY)
412	        {
413	          /* Delivery failed, which means the agent is not draining its bus.
414	           * Without a backoff here this would retry every VG_ADV_MIN_GAP_MS
415	           * and fill that 16-deep queue by itself, so take the same pause as
416	           * a round that produced nothing usable. */
417	
418	          pthread_mutex_lock(&g_lock);
419	          g_next_ask_ms = now + VG_ADV_RETRY_MS;
420	          g_asked_once = true;
421	          g_last_ask_ms = now;
422	          pthread_mutex_unlock(&g_lock);
423	        }
424	
425	      /* -EBUSY is the other flow holding the channel for one tick; asking
426	       * again on the next tick is the right move, not a five minute pause. */
427	
428	      advice_set_state(VG_UI_ADV_ERROR);
429	      return;
430	    }
431	
432	  pthread_mutex_lock(&g_lock);
433	  g_last_ask_ms = now;
434	  g_next_ask_ms = 0;
435	  g_asked_once = true;
436	  pthread_mutex_unlock(&g_lock);
437	
438	  advice_set_state(VG_UI_ADV_PENDING);
439	
440	  syslog(LOG_INFO, "[%s] asked for %d alarms\n", TAG, n);
441	#else
442	  /* HMI without the agent: the page keeps showing the rule summary. */
443	
444	  advice_drop();
445	#endif
446	}
