443	/* AI advice block for the selected alarm.
444	 *
445	 * The only source of AI text is a cache entry the board already validated
446	 * against the VGADV1 contract, so there is no path here that can invent an
447	 * explanation.  Everything else -- still generating, failed, offline, or a
448	 * plain miss -- keeps the deterministic rule summary that render_detail
449	 * just built, and only the heading changes to say why. */
450	static void render_ai_detail(const vg_alarm_t * a, const vg_sensor_t * as,
451	                             const char * rule_text)
452	{
453	    vg_ai_advice_entry_t adv;
454	    uint32_t epoch = (as != NULL) ? as->al_epoch : 0;
455	    char body[640];
456	    const char * head;
457	
458	    if(as != NULL && vg_ui_alarm_advice_get(a->sensor_id, epoch, &adv)) {
459	        lv_snprintf(body, sizeof(body),
460	                    "【AI 建议】%s\n【依据】%s\n【建议关注】%s%s",
461	                    adv.sum,
462	                    adv.ev[0] ? adv.ev : "（未给出）",
463	                    adv.att[0] ? adv.att : "（未给出）",
464	                    adv.unresolved ? "\n证据不足，未能给出确定结论" : "");
465	        set_ai_block("OPENVELACLAW 建议（AI 推测）", body);
466	        return;
467	    }
468	
469	    switch(vg_ui_alarm_advice_state()) {
470	        case VG_UI_ADV_PENDING:
471	            head = "AI 建议生成中，暂显示规则摘要";
472	            break;
473	        case VG_UI_ADV_ERROR:
474	            head = "AI 建议不可用，显示规则摘要";
475	            break;
476	        default:
477	            head = "规则摘要（本地）";
478	            break;
479	    }
480	
481	    set_ai_block(head, rule_text);
482	}
