39	uint32_t vg_agent_round_now_ms(void)
40	{
41	  struct timespec ts;
42	
43	  (void)clock_gettime(CLOCK_MONOTONIC, &ts);
44	  return (uint32_t)((uint64_t)ts.tv_sec * 1000u
45	                    + (uint64_t)ts.tv_nsec / 1000000u);
46	}
