48	/* Runs on the agent's outbound dispatch thread, so it only records the
49	 * outcome and never blocks on anything but this mutex. */
50	
51	static void round_reply(int status, const char *text, void *cookie)
52	{
53	  (void)cookie;
54	
55	  pthread_mutex_lock(&g_lock);
56	  g_reply_seen = true;
57	  g_reply_ok = (status == 0);
58	
59	  if (text != NULL)
60	    {
61	      strncpy(g_reply, text, sizeof(g_reply) - 1);
62	      g_reply[sizeof(g_reply) - 1] = '\0';
63	    }
64	  else
65	    {
66	      g_reply[0] = '\0';
67	    }
68	
69	  pthread_mutex_unlock(&g_lock);
70	}
