72	int vg_agent_round_init(void)
73	{
74	  int rc = 0;
75	
76	  pthread_mutex_lock(&g_lock);
77	
78	  if (g_client == NULL)
79	    {
80	      /* Fails while the agent's message bus is still coming up; the worker
81	       * retries on later ticks until VG_AGENT_ROUND_QUEUE_TIMEOUT_MS. */
82	
83	      g_client = velaclaw_client_open("velaguard");
84	      if (g_client != NULL)
85	        {
86	          syslog(LOG_INFO, "[%s] local agent client ready\n", TAG);
87	        }
88	    }
89	
90	  if (g_client == NULL)
91	    {
92	      rc = -ENODEV;
93	    }
94	
95	  pthread_mutex_unlock(&g_lock);
96	  return rc;
97	}
