99	int vg_agent_round_queue(const char *text)
100	{
101	  return vg_agent_round_queue_owned(text, VG_AGENT_ROUND_OWNER_NONE);
102	}
103	
104	int vg_agent_round_queue_owned(const char *text,
105	                               enum vg_agent_round_owner owner)
106	{
107	  size_t len;
108	
109	  if (text == NULL)
110	    {
111	      return -EINVAL;
112	    }
113	
114	  len = strlen(text);
115	  if (len == 0)
116	    {
117	      return -EINVAL;
118	    }
119	
120	  if (len >= VG_ROUND_REQ_MAX)
121	    {
122	      return -E2BIG;
123	    }
124	
125	  pthread_mutex_lock(&g_lock);
126	
127	  /* A finished result that its owner has not read yet is not free: letting
128	   * another flow overwrite it would discard an artifact that is already on
129	   * eMMC.  Both consumers clear their own result within a tick, so this only
130	   * ever costs the new request one worker iteration. */
131	
132	  if (g_state != VG_AGENT_ROUND_IDLE)
133	    {
134	      pthread_mutex_unlock(&g_lock);
135	      return -EBUSY;
136	    }
137	
138	  memcpy(g_req, text, len + 1);
139	  g_owner = owner;
140	  g_state = VG_AGENT_ROUND_QUEUED;
141	  g_started_ms = vg_agent_round_now_ms();
142	  g_reply_seen = false;
143	  g_reply_ok = false;
144	  g_reply[0] = '\0';
145	
146	  pthread_mutex_unlock(&g_lock);
147	  return 0;
148	}
149	
150	static void round_submit(void)
151	{
152	  /* Function-local so a 1.5 KB request never lands on the worker stack, and
153	   * released before the call so the reply callback can never contend with us
154	   * on the same lock if a build ever dispatches replies synchronously. */
155	
156	  static char req[VG_ROUND_REQ_MAX];
157	  velaclaw_client_t *client;
158	  velaclaw_ask_req_t ask;
159	  int rc;
160	
161	  pthread_mutex_lock(&g_lock);
162	  if (g_client == NULL)
163	    {
164	      pthread_mutex_unlock(&g_lock);
165	
166	      if (vg_agent_round_init() != 0)
167	        {
168	          return;
169	        }
170	
171	      pthread_mutex_lock(&g_lock);
172	    }
173	
174	  client = g_client;
175	  memcpy(req, g_req, sizeof(req));
176	  pthread_mutex_unlock(&g_lock);
177	
178	  ask.text = req;
179	  ask.timeout_ms = (int)VG_AGENT_ROUND_TIMEOUT_MS;
180	
181	  rc = velaclaw_ask_async(client, &ask, round_reply, NULL);
182	
183	  pthread_mutex_lock(&g_lock);
184	  if (rc == 0)
185	    {
186	      g_state = VG_AGENT_ROUND_RUNNING;
187	      g_started_ms = vg_agent_round_now_ms();
188	      syslog(LOG_INFO, "[%s] round submitted: %u bytes\n",
189	             TAG, (unsigned)strlen(req));
190	    }
191	  else
192	    {
193	      g_state = VG_AGENT_ROUND_ERROR;
194	      g_finished_ms = vg_agent_round_now_ms();
195	      syslog(LOG_WARNING, "[%s] round submit failed: %d\n", TAG, rc);
196	    }
197	
198	  pthread_mutex_unlock(&g_lock);
199	}
200	
201	void vg_agent_round_tick(void)
202	{
203	  enum vg_agent_round_state st;
204	  uint32_t started;
205	  uint32_t now = vg_agent_round_now_ms();
206	  bool seen;
207	  bool ok;
208	
209	  pthread_mutex_lock(&g_lock);
210	  st = g_state;
211	  started = g_started_ms;
212	  pthread_mutex_unlock(&g_lock);
213	
214	  if (st == VG_AGENT_ROUND_QUEUED)
215	    {
216	      /* Two tickers are possible (the HMI file worker and the vgagent NSH
217	       * probe), and only one of them may push a given request. */
218	
219	      pthread_mutex_lock(&g_lock);
220	      if (g_submitting || g_state != VG_AGENT_ROUND_QUEUED)
221	        {
222	          pthread_mutex_unlock(&g_lock);
223	          return;
224	        }
225	
226	      g_submitting = true;
227	      pthread_mutex_unlock(&g_lock);
228	
229	      round_submit();
230	
231	      /* A queued request that never got delivered (agent bus absent) must
232	       * not hold the slot forever. */
233	
234	      pthread_mutex_lock(&g_lock);
235	      g_submitting = false;
236	      if (g_state == VG_AGENT_ROUND_QUEUED &&
237	          now - started >= VG_AGENT_ROUND_QUEUE_TIMEOUT_MS)
238	        {
239	          g_state = VG_AGENT_ROUND_ERROR;
240	          g_finished_ms = vg_agent_round_now_ms();
241	          syslog(LOG_WARNING, "[%s] round never reached the agent\n", TAG);
242	        }
243	      pthread_mutex_unlock(&g_lock);
244	      return;
245	    }
246	
247	  if (st != VG_AGENT_ROUND_RUNNING)
248	    {
249	      return;
250	    }
251	
252	  pthread_mutex_lock(&g_lock);
253	  seen = g_reply_seen;
254	  ok = g_reply_ok;
255	  g_reply_seen = false;
256	  pthread_mutex_unlock(&g_lock);
257	
258	  if (seen)
259	    {
260	      pthread_mutex_lock(&g_lock);
261	      if (ok)
262	        {
263	          g_state = VG_AGENT_ROUND_DONE;
264	          g_generation++;
265	        }
266	      else
267	        {
268	          g_state = VG_AGENT_ROUND_ERROR;
269	        }
270	
271	      g_finished_ms = vg_agent_round_now_ms();
272	      pthread_mutex_unlock(&g_lock);
273	
274	      syslog(LOG_INFO, "[%s] round finished: %s\n",
275	             TAG, ok ? "reply" : "agent error");
276	      return;
277	    }
278	
279	  if (now - started >= VG_AGENT_ROUND_TIMEOUT_MS)
280	    {
281	      pthread_mutex_lock(&g_lock);
282	      g_state = VG_AGENT_ROUND_ERROR;
283	      g_finished_ms = vg_agent_round_now_ms();
284	      pthread_mutex_unlock(&g_lock);
285	      syslog(LOG_WARNING, "[%s] round timed out after %u ms\n",
286	             TAG, (unsigned)(now - started));
287	    }
288	}
289	
290	enum vg_agent_round_state vg_agent_round_state(void)
291	{
292	  enum vg_agent_round_state st;
293	
294	  pthread_mutex_lock(&g_lock);
295	  st = g_state;
296	  pthread_mutex_unlock(&g_lock);
297	  return st;
298	}
