303	
304	  return (st == VG_AGENT_ROUND_QUEUED || st == VG_AGENT_ROUND_RUNNING);
305	}
306	
307	uint32_t vg_agent_round_generation(void)
308	{
309	  uint32_t gen;
310	
311	  pthread_mutex_lock(&g_lock);
312	  gen = g_generation;
313	  pthread_mutex_unlock(&g_lock);
