315	}
316	
317	enum vg_agent_round_owner vg_agent_round_owner(void)
318	{
319	  enum vg_agent_round_owner owner;
320	
321	  pthread_mutex_lock(&g_lock);
322	  owner = g_owner;
323	  pthread_mutex_unlock(&g_lock);
