325	}
326	
327	bool vg_agent_round_reclaim(enum vg_agent_round_owner mine, uint32_t grace_ms)
328	{
329	  bool released = false;
330	
331	  pthread_mutex_lock(&g_lock);
332	
333	  if ((g_state == VG_AGENT_ROUND_DONE || g_state == VG_AGENT_ROUND_ERROR) &&
334	      g_owner != mine && g_finished_ms != 0 &&
335	      vg_agent_round_now_ms() - g_finished_ms >= grace_ms)
336	    {
337	      /* Somebody else's finished round that nobody is going to read - a
338	       * manual round killed half way, or a flow that went away.  Without
339	       * this the strict queue would hold the channel for it forever. */
340	
341	      g_state = VG_AGENT_ROUND_IDLE;
342	      g_owner = VG_AGENT_ROUND_OWNER_NONE;
343	      released = true;
344	    }
345	
346	  pthread_mutex_unlock(&g_lock);
347	  return released;
348	}
349	
350	void vg_agent_round_clear(void)
351	{
352	  pthread_mutex_lock(&g_lock);
353	
354	  if (g_state == VG_AGENT_ROUND_DONE || g_state == VG_AGENT_ROUND_ERROR)
355	    {
356	      g_state = VG_AGENT_ROUND_IDLE;
357	      g_owner = VG_AGENT_ROUND_OWNER_NONE;
358	      g_finished_ms = 0;
359	    }
360	
361	  pthread_mutex_unlock(&g_lock);
362	}
