/****************************************************************************
 * app/velaguard/vg_advice_policy.h
 *
 * Decisions for the board-side per-point alarm advice, kept apart from the
 * threads, the filesystem and the model so app/velaguard/host_tests can
 * exercise them.
 *
 * The rule this module exists to hold: whether the page may show AI text
 * depends on whether a validated entry matches the alarm episode on screen.
 * It never depends on how the last round went, so a refresh that fails
 * cannot blank advice that is still correct for the alarm the reader is
 * looking at.
 *
 * Deliberately free of LVGL, cJSON and NuttX headers, same as
 * vg_ai_contract.h.
 ****************************************************************************/

#ifndef __APP_VELAGUARD_VG_ADVICE_POLICY_H
#define __APP_VELAGUARD_VG_ADVICE_POLICY_H

#include <stdbool.h>
#include <stdint.h>

#include "vg_ai_contract.h"

/****************************************************************************
 * Hit rule
 *
 * Single source of truth for "does the page have advice for this alarm".
 * Note what is absent from the signature: the state of the last round.  A
 * round that timed out or was rejected leaves the loaded document in place,
 * and that document is still the right answer for the alarm it was written
 * about.
 ****************************************************************************/

bool vg_advice_lookup(bool loaded, const vg_ai_advice_doc_t *doc,
                      const char *id, uint32_t epoch,
                      vg_ai_advice_entry_t *out);

/****************************************************************************
 * Document coverage
 *
 * sig is the alarm-set signature built by vg_advice.c (id, epoch and
 * severity of every active alarm).  doc_sig is the signature of the set the
 * loaded document answers.  They match exactly when the advice on hand was
 * written for the alarms currently on screen.
 ****************************************************************************/

bool vg_advice_covers(bool loaded, const char *doc_sig, const char *sig);

/****************************************************************************
 * What the page is told after a round ended without a document the parser
 * accepted.
 ****************************************************************************/

typedef enum
{
  /* The loaded document still answers the current alarm set: keep showing
   * it.  The failed round changed nothing the reader can see. */

  VG_ADV_AFTER_ROUND_READY = 0,

  /* Nothing behind this alarm set, so the page says advice is unavailable
   * and falls back to the rule summary. */

  VG_ADV_AFTER_ROUND_ERROR
} vg_advice_after_round_t;

vg_advice_after_round_t vg_advice_after_round(bool covered);

/****************************************************************************
 * Whether to spend another LLM round
 ****************************************************************************/

typedef struct
{
  const char *sig;              /* current alarm set */
  const char *doc_sig;          /* set the loaded document answers */
  const char *backoff_sig;      /* set the armed retry pause belongs to */
  bool        loaded;
  bool        asked_once;       /* an ask has happened since boot */
  bool        backoff_armed;    /* a retry pause is set */
  bool        backoff_expired;  /* ... and its time is up */
  bool        refresh_due;      /* the covering document has aged out */
  uint32_t    since_last_ask_ms;
  uint32_t    min_gap_ms;
} vg_advice_gate_t;

typedef enum
{
  VG_ADV_ASK = 0,
  VG_ADV_SKIP_COVERED,    /* have it, and it is not stale yet */
  VG_ADV_SKIP_BACKOFF,    /* this very set already came back empty */
  VG_ADV_SKIP_MIN_GAP     /* asked too recently */
} vg_advice_decision_t;

vg_advice_decision_t vg_advice_decide(const vg_advice_gate_t *g);

/****************************************************************************
 * Queue outcome classification.
 *
 * -EBUSY is the other flow holding the single round channel for one tick.
 * It says nothing about this flow's advice, so it must not be reported as a
 * failure: the page would blink to "unavailable" every time the daily report
 * took the channel.
 ****************************************************************************/

bool vg_advice_queue_is_transient(int rc);

#endif /* __APP_VELAGUARD_VG_ADVICE_POLICY_H */

/****************************************************************************
 * app/velaguard/vg_advice_policy.c
 *
 * See vg_advice_policy.h.  Pure functions, no state of their own: every
 * input arrives as an argument so host_tests can pin each rule.
 ****************************************************************************/

#include <errno.h>
#include <string.h>

#include "vg_advice_policy.h"

bool vg_advice_lookup(bool loaded, const vg_ai_advice_doc_t *doc,
                      const char *id, uint32_t epoch,
                      vg_ai_advice_entry_t *out)
{
  const vg_ai_advice_entry_t *e;

  if (!loaded || doc == NULL || id == NULL || out == NULL)
    {
      return false;
    }

  e = vg_ai_advice_find(doc, id, epoch);
  if (e == NULL)
    {
      return false;
    }

  *out = *e;
  return true;
}

bool vg_advice_covers(bool loaded, const char *doc_sig, const char *sig)
{
  /* An empty signature means "no active alarm set", which nothing covers. */

  if (!loaded || doc_sig == NULL || sig == NULL || sig[0] == '\0')
    {
      return false;
    }

  return (strcmp(doc_sig, sig) == 0);
}

vg_advice_after_round_t vg_advice_after_round(bool covered)
{
  return covered ? VG_ADV_AFTER_ROUND_READY : VG_ADV_AFTER_ROUND_ERROR;
}

vg_advice_decision_t vg_advice_decide(const vg_advice_gate_t *g)
{
  bool same_set;

  if (g == NULL)
    {
      return VG_ADV_SKIP_BACKOFF;
    }

  /* Advice for the alarm set on screen is only worth replacing once it has
   * aged out. */

  if (vg_advice_covers(g->loaded, g->doc_sig, g->sig))
    {
      return g->refresh_due ? VG_ADV_ASK : VG_ADV_SKIP_COVERED;
    }

  /* Nothing covers this set, so one round per set per pause.  A set that
   * changed while a pause was armed is a different question and may be asked
   * at once: that is what keeps a re-raised alarm from waiting out the
   * previous set's pause after a failed round. */

  same_set = g->backoff_armed && g->backoff_sig != NULL && g->sig != NULL &&
             g->backoff_sig[0] != '\0' &&
             strcmp(g->backoff_sig, g->sig) == 0;

  if (same_set && !g->backoff_expired)
    {
      return VG_ADV_SKIP_BACKOFF;
    }

  if (g->asked_once && g->since_last_ask_ms < g->min_gap_ms)
    {
      return VG_ADV_SKIP_MIN_GAP;
    }

  return VG_ADV_ASK;
}

bool vg_advice_queue_is_transient(int rc)
{
  return (rc == -EBUSY);
}

