static void advice_load(void)
{
  uint32_t boot;
  uint32_t req;
  int fd;
  ssize_t got;
  int rc;

  /* Read the round identity first so every log line below can name it: a
   * rejected document is only diagnosable together with the req it was
   * supposed to answer. */

  pthread_mutex_lock(&g_lock);
  boot = g_boot;
  req = g_req;
  pthread_mutex_unlock(&g_lock);

  fd = open(VG_ADV_FILE, O_RDONLY);
  if (fd < 0)
    {
      syslog(LOG_WARNING, "[%s] no advice file (%d) boot=%08x req=%u\n",
             TAG, errno, (unsigned)boot, (unsigned)req);
      advice_set_state(VG_UI_ADV_ERROR);
      return;
    }

  got = read(fd, s_raw, sizeof(s_raw) - 1);
  close(fd);

  if (got <= 0)
    {
      syslog(LOG_WARNING, "[%s] advice file empty (%d) req=%u\n",
             TAG, (int)got, (unsigned)req);
      advice_set_state(VG_UI_ADV_ERROR);
      return;
    }

  s_raw[got] = '\0';

  rc = vg_ai_advice_parse(s_raw, (size_t)got, boot, req, &s_parsed);
  if (rc != VG_AI_OK)
    {
      /* Rejected whole: the page keeps showing the rule summary, and the
       * rejection is recorded rather than half-applied.  A document left over
       * from an earlier round lands here as VG_AI_ERR_STALE. */

      syslog(LOG_WARNING, "[%s] advice rejected rc=%d (%d bytes) req=%u\n",
             TAG, rc, (int)got, (unsigned)req);
      advice_set_state(VG_UI_ADV_ERROR);
      return;
    }

  pthread_mutex_lock(&g_lock);
  g_doc = s_parsed;
  g_loaded = true;
  g_state = VG_UI_ADV_READY;
  g_last_ok_ms = vg_agent_round_now_ms();
  g_next_ask_ms = 0;
  g_backoff_sig[0] = '\0';
  /* The document answers g_sig: that is the set the request was built from,
   * and it stays put for the whole round. */
  memcpy(g_doc_sig, g_sig, sizeof(g_doc_sig));
  pthread_mutex_unlock(&g_lock);

  syslog(LOG_INFO, "[%s] advice loaded: %d entries req=%u\n",
         TAG, s_parsed.n, (unsigned)req);
}

static void advice_drop(void)
{
  pthread_mutex_lock(&g_lock);

  if (g_loaded || g_state != VG_UI_ADV_IDLE)
    {
      g_loaded = false;
      g_state = VG_UI_ADV_IDLE;
      g_sig[0] = '\0';
      g_doc_sig[0] = '\0';
      g_backoff_sig[0] = '\0';
      g_asked_once = false;
      g_next_ask_ms = 0;
    }

  pthread_mutex_unlock(&g_lock);
}

