300	#ifdef CONFIG_EXAMPLES_AI_AGENT_VELA
301	  static char req[VG_ADV_REQ_MAX];
302	  static vg_advice_alarm_t snap[VG_AI_ADV_MAX];
303	  vg_ai_alarm_in_t in[VG_AI_ADV_MAX];
304	  char sig[VG_ADV_SIG_MAX];
305	  uint32_t now = vg_agent_round_now_ms();
306	  enum vg_agent_round_state rnd;
307	  bool changed;
308	  bool refresh;
309	  bool due;
310	  int n;
311	  int i;
312	  int len;
313	  int rc;
314	
315	  pthread_mutex_lock(&g_snap_lock);
316	  memcpy(snap, g_snap, sizeof(snap));
317	  n = g_snap_n;
318	  pthread_mutex_unlock(&g_snap_lock);
319	
320	  if (n <= 0)
321	    {
322	      /* Release our own finished round first: the queue refuses to start a
323	       * new round while any result is still unconsumed. */
324	
325	      if (vg_agent_round_owner() == VG_AGENT_ROUND_OWNER_ADVICE)
326	        {
327	          enum vg_agent_round_state rst = vg_agent_round_state();
328	
329	          if (rst == VG_AGENT_ROUND_DONE || rst == VG_AGENT_ROUND_ERROR)
330	            {
331	              vg_agent_round_clear();
332	            }
333	        }
334	
335	      advice_drop();
336	      return;
337	    }
338	
339	  build_sig(sig, sizeof(sig), snap, n);
340	
341	  /* A round is in flight: nothing to do but wait. */
342	
343	  if (vg_agent_round_busy())
344	    {
345	      advice_set_state(VG_UI_ADV_PENDING);
346	      return;
347	    }
348	
349	  /* A finished round nobody claimed - a manual one whose process went away,
350	   * most likely - would hold the channel forever now that the queue refuses
351	   * to start a round while a terminal state is present. */
352	
353	  vg_agent_round_reclaim(VG_AGENT_ROUND_OWNER_ADVICE,
354	                         VG_AGENT_ROUND_RECLAIM_MS);
355	
356	  /* A round just ended (or failed).  Only a round this flow asked for says
357	   * anything about alarm_advice.txt: the daily flow shares the channel and
358	   * its reply is a different file.  A round owned by the other flow is left
359	   * alone here, and this tick carries on to the asking logic below. */
360	
361	  rnd = vg_agent_round_state();
362	  if ((rnd == VG_AGENT_ROUND_DONE || rnd == VG_AGENT_ROUND_ERROR) &&
363	      vg_agent_round_owner() == VG_AGENT_ROUND_OWNER_ADVICE)
364	    {
365	      if (rnd == VG_AGENT_ROUND_DONE)
366	        {
367	          advice_load();
368	        }
369	      else
370	        {
371	          advice_set_state(VG_UI_ADV_ERROR);
372	        }
373	
374	      /* The round ended without a document the parser accepted.  Hold the
375	       * same alarm set off for a while: a rejected or missing file is not
376	       * going to fix itself in the next 20 s, and each retry costs a full
377	       * LLM round. */
378	
379	      pthread_mutex_lock(&g_lock);
380	      if (!g_loaded)
381	        {
382	          g_next_ask_ms = now + VG_ADV_RETRY_MS;
383	        }
384	      pthread_mutex_unlock(&g_lock);
385	
386	      vg_agent_round_clear();
387	    }
388	
389	  /* Read the gate after the round bookkeeping above, so a backoff armed by
390	   * the round that just ended is already in effect for this tick. */
391	
392	  pthread_mutex_lock(&g_lock);
393	  changed = (strcmp(sig, g_sig) != 0);
394	  refresh = g_loaded && g_last_ok_ms != 0 &&
395	            now - g_last_ok_ms >= VG_ADV_REFRESH_MS;
396	  due = changed || g_next_ask_ms == 0 ||
397	        (int32_t)(now - g_next_ask_ms) >= 0;
398	  pthread_mutex_unlock(&g_lock);
399	
400	  if (!changed && !refresh && g_loaded)
401	    {
402	      return;
403	    }
404	
405	  if (!due)
406	    {
407	      return;
408	    }
409	
410	  if (g_asked_once && now - g_last_ask_ms < VG_ADV_MIN_GAP_MS)
411	    {
412	      return;
413	    }
414	
415	  memset(in, 0, sizeof(in));
416	  for (i = 0; i < n; i++)
417	    {
418	      in[i].id = snap[i].id;
419	      in[i].name = snap[i].name;
420	      in[i].epoch = snap[i].epoch;
421	      in[i].sev = snap[i].sev;
422	      in[i].value = snap[i].value;
423	      in[i].threshold = snap[i].threshold;
424	      in[i].dur_s = snap[i].dur_s;
425	    }
426	
427	  pthread_mutex_lock(&g_lock);
428	  g_req++;
429	  len = vg_ai_advice_build_request(req, sizeof(req), advice_boot_nonce(),
430	                                   g_req, in, n);
431	  if (len > 0)
432	    {
433	      memcpy(g_sig, sig, sizeof(g_sig));
434	      g_sig[sizeof(g_sig) - 1] = '\0';
435	    }
436	  pthread_mutex_unlock(&g_lock);
437	
438	  if (len <= 0)
439	    {
440	      syslog(LOG_WARNING, "[%s] request build failed: %d\n", TAG, len);
441	      advice_set_state(VG_UI_ADV_ERROR);
442	      return;
443	    }
444	
445	  rc = vg_agent_round_queue_owned(req, VG_AGENT_ROUND_OWNER_ADVICE);
446	  if (rc != 0)
447	    {
448	      if (rc != -EBUSY)
449	        {
450	          /* Delivery failed, which means the agent is not draining its bus.
451	           * Without a backoff here this would retry every VG_ADV_MIN_GAP_MS
452	           * and fill that 16-deep queue by itself, so take the same pause as
453	           * a round that produced nothing usable. */
454	
455	          pthread_mutex_lock(&g_lock);
456	          g_next_ask_ms = now + VG_ADV_RETRY_MS;
457	          g_asked_once = true;
458	          g_last_ask_ms = now;
459	          pthread_mutex_unlock(&g_lock);
460	        }
461	
462	      /* -EBUSY is the other flow holding the channel for one tick; asking
463	       * again on the next tick is the right move, not a five minute pause. */
464	
465	      advice_set_state(VG_UI_ADV_ERROR);
466	      return;
467	    }
468	
469	  pthread_mutex_lock(&g_lock);
470	  g_last_ask_ms = now;
471	  g_next_ask_ms = 0;
472	  g_asked_once = true;
473	  pthread_mutex_unlock(&g_lock);
474	
475	  advice_set_state(VG_UI_ADV_PENDING);
476	
477	  syslog(LOG_INFO, "[%s] asked for %d alarms\n", TAG, n);
478	#else
479	  /* HMI without the agent: the page keeps showing the rule summary. */
480	
481	  advice_drop();
482	#endif
483	}
