  got = read(fd, s_raw, sizeof(s_raw) - 1);
  close(fd);

  if (got <= 0)
    {
      syslog(LOG_WARNING, "[%s] advice file empty (%d) req=%u\n",
             TAG, (int)got, (unsigned)req);
      advice_set_state(VG_UI_ADV_ERROR);
      return;
    }

  s_raw[got] = '\0';

  rc = vg_ai_advice_parse(s_raw, (size_t)got, boot, req, &s_parsed);
  if (rc != VG_AI_OK)
