       * rejection is recorded rather than half-applied.  A document left over
       * from an earlier round lands here as VG_AI_ERR_STALE. */

      syslog(LOG_WARNING, "[%s] advice rejected rc=%d (%d bytes) req=%u\n",
             TAG, rc, (int)got, (unsigned)req);
      advice_set_state(VG_UI_ADV_ERROR);
      return;
