  pthread_mutex_lock(&g_lock);
  g_doc = s_parsed;
  g_loaded = true;
  g_state = VG_UI_ADV_READY;
  g_last_ok_ms = vg_agent_round_now_ms();
  g_next_ask_ms = 0;
  g_backoff_sig[0] = '\0';
  /* The document answers g_sig: that is the set the request was built from,
   * and it stays put for the whole round. */
  memcpy(g_doc_sig, g_sig, sizeof(g_doc_sig));
  pthread_mutex_unlock(&g_lock);

  syslog(LOG_INFO, "[%s] advice loaded: %d entries req=%u\n",
         TAG, s_parsed.n, (unsigned)req);
