# VelaGuard bench helper: Modbus RTU slave simulator on a PC COM port.
#
# It only ANSWERS the board's RS485 master; it never issues a request, so the
# single-master rule on that bus holds.  Register values come from a text file
# so a scenario can be changed without restarting:
#
#   <slave>:<reg>=<value>        e.g.  1:0=360     (slave 1, reg 0, 360)
#
# Usage:
#   powershell.exe -ExecutionPolicy Bypass -File vg_slave_sim.ps1 `
#     -ComPort 4 -Values C:\Users\Public\vgslave_regs.txt
#
# The port is opened 9600 8N1, matching the board's fixed stage-1 rate.

param(
  [string]$ComPort = "COM4",
  [int]$Baud = 9600,
  [string]$Values = "C:\Users\Public\vgslave_regs.txt",
  [int]$KeepSeconds = 0
)

$ErrorActionPreference = "Stop"

$src = @'
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.IO.Ports;

public class VgSlaveSim
{
    static ushort[,] regs = new ushort[8, 16];
    static string valueFile;
    static DateTime lastWrite = DateTime.MinValue;

    static ushort Crc(byte[] data, int len)
    {
        ushort crc = 0xFFFF;
        for (int i = 0; i < len; i++)
        {
            crc ^= data[i];
            for (int b = 0; b < 8; b++)
            {
                if ((crc & 1) != 0) crc = (ushort)((crc >> 1) ^ 0xA001);
                else crc = (ushort)(crc >> 1);
            }
        }
        return crc;
    }

    static void LoadValues()
    {
        try
        {
            if (!File.Exists(valueFile)) return;
            DateTime t = File.GetLastWriteTime(valueFile);
            if (t == lastWrite) return;

            ushort[,] next = new ushort[8, 16];
            foreach (string raw in File.ReadAllLines(valueFile))
            {
                string line = raw.Trim();
                if (line.Length == 0 || line.StartsWith("#")) continue;

                int colon = line.IndexOf(':');
                int eq = line.IndexOf('=');
                if (colon < 0 || eq < 0 || colon > eq) continue;

                int addr, reg, val;
                if (!int.TryParse(line.Substring(0, colon), NumberStyles.Integer,
                                  CultureInfo.InvariantCulture, out addr)) continue;
                if (!int.TryParse(line.Substring(colon + 1, eq - colon - 1),
                                  NumberStyles.Integer, CultureInfo.InvariantCulture,
                                  out reg)) continue;
                if (!int.TryParse(line.Substring(eq + 1), NumberStyles.Integer,
                                  CultureInfo.InvariantCulture, out val)) continue;
                if (addr < 1 || addr > 7 || reg < 0 || reg > 15) continue;

                next[addr, reg] = (ushort)(val & 0xFFFF);
            }

            regs = next;
            lastWrite = t;
            Console.WriteLine("[sim] values loaded " + DateTime.Now.ToString("HH:mm:ss"));
        }
        catch (Exception e)
        {
            Console.WriteLine("[sim] value load failed: " + e.Message);
        }
    }

    static void SendException(SerialPort sp, byte addr, byte fc, byte code)
    {
        byte[] f = new byte[5];
        f[0] = addr;
        f[1] = fc;
        f[2] = code;
        ushort c = Crc(f, 3);
        f[3] = (byte)(c & 0xFF);
        f[4] = (byte)(c >> 8);
        sp.Write(f, 0, f.Length);
    }

    static bool Respond(SerialPort sp, byte[] f, ref int served)
    {
        if (f.Length < 8) return false;

        ushort crc = Crc(f, f.Length - 2);
        ushort got = (ushort)(f[f.Length - 2] | (f[f.Length - 1] << 8));
        if (crc != got)
        {
            Console.WriteLine("[sim] bad crc from bus");
            return false;
        }

        byte addr = f[0];
        byte fc = f[1];
        int start = (f[2] << 8) | f[3];
        int qty = (f[4] << 8) | f[5];

        // Slaves we do not model stay silent, exactly like an absent device.
        if (addr < 1 || addr > 7) return false;
        if (fc != 3) return false;
        if (qty < 1 || start < 0 || start + qty > 16)
        {
            SendException(sp, addr, (byte)(fc | 0x80), 2);
            return true;
        }

        List<byte> resp = new List<byte>();
        resp.Add(addr);
        resp.Add(fc);
        resp.Add((byte)(qty * 2));
        for (int i = 0; i < qty; i++)
        {
            ushort v = regs[addr, start + i];
            resp.Add((byte)(v & 0xFF));
            resp.Add((byte)(v >> 8));
        }

        byte[] body = resp.ToArray();
        ushort rc = Crc(body, body.Length);
        byte[] outb = new byte[body.Length + 2];
        Array.Copy(body, outb, body.Length);
        outb[body.Length] = (byte)(rc & 0xFF);
        outb[body.Length + 1] = (byte)(rc >> 8);

        // One write: the board's byte timeout is 20 ms, so the reply has to
        // leave the port as a contiguous burst.
        sp.Write(outb, 0, outb.Length);
        served++;

        if (served <= 8 || served % 500 == 0)
        {
            Console.WriteLine("[sim] #" + served + " slave=" + addr + " start=" + start +
                              " qty=" + qty + " -> " + regs[addr, start]);
        }
        return true;
    }

    public static void Run(string portName, int baud, string file)
    {
        valueFile = file;
        if (!File.Exists(valueFile))
        {
            Directory.CreateDirectory(Path.GetDirectoryName(valueFile));
            File.WriteAllText(valueFile, "# <slave>:<reg>=<value>\r\n");
        }
        LoadValues();

        SerialPort sp = new SerialPort(portName, baud, Parity.None, 8, StopBits.One);
        sp.ReadTimeout = 25;
        sp.WriteTimeout = 500;
        sp.Open();
        Console.WriteLine("[sim] " + portName + " open @" + baud +
                          " 8N1; answering only, never requesting");

        List<byte> buf = new List<byte>();
        byte[] one = new byte[1];
        int served = 0;
        int idleTicks = 0;
        DateTime lastBeat = DateTime.Now;

        while (true)
        {
            bool got = false;
            try
            {
                int n = sp.Read(one, 0, 1);
                if (n > 0) { buf.Add(one[0]); got = true; }
            }
            catch (TimeoutException) { }

            if (buf.Count >= 8)
            {
                byte[] frame = buf.ToArray();
                buf.Clear();
                Respond(sp, frame, ref served);
                idleTicks = 0;
                continue;
            }

            if (!got)
            {
                // A partial frame that stopped mid-way is noise, not a request.
                if (buf.Count > 0 && buf.Count < 8) buf.Clear();

                idleTicks++;
                if ((DateTime.Now - lastBeat).TotalSeconds >= 10)
                {
                    Console.WriteLine("[sim] alive, served=" + served);
                    lastBeat = DateTime.Now;
                    LoadValues();
                }
            }
        }
    }
}
