using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.IO.Ports;
using System.Threading;

public class VgSlaveSim
{
    static ushort[,] regs = new ushort[8, 16];
    static string valueFile;
    static DateTime lastWrite = DateTime.MinValue;

    static ushort Crc(byte[] data, int len)
    {
        ushort crc = 0xFFFF;
        for (int i = 0; i < len; i++)
        {
            crc ^= data[i];
            for (int b = 0; b < 8; b++)
            {
                if ((crc & 1) != 0) crc = (ushort)((crc >> 1) ^ 0xA001);
                else crc = (ushort)(crc >> 1);
            }
        }
        return crc;
    }

    static void LoadValues()
    {
        try
        {
            if (!File.Exists(valueFile)) return;
            DateTime t = File.GetLastWriteTime(valueFile);
            if (t == lastWrite) return;

            ushort[,] next = new ushort[8, 16];
            foreach (string raw in File.ReadAllLines(valueFile))
            {
                string line = raw.Trim();
                if (line.Length == 0 || line.StartsWith("#")) continue;

                int colon = line.IndexOf(':');
                int eq = line.IndexOf('=');
                if (colon < 0 || eq < 0 || colon > eq) continue;

                int addr, reg, val;
                if (!int.TryParse(line.Substring(0, colon), NumberStyles.Integer,
                                  CultureInfo.InvariantCulture, out addr)) continue;
                if (!int.TryParse(line.Substring(colon + 1, eq - colon - 1),
                                  NumberStyles.Integer, CultureInfo.InvariantCulture,
                                  out reg)) continue;
                if (!int.TryParse(line.Substring(eq + 1), NumberStyles.Integer,
                                  CultureInfo.InvariantCulture, out val)) continue;
                if (addr < 1 || addr > 7 || reg < 0 || reg > 15) continue;

                next[addr, reg] = (ushort)(val & 0xFFFF);
            }

            regs = next;
            lastWrite = t;
            Console.WriteLine("[sim] values loaded: " + ValuesText());
        }
        catch (Exception e)
        {
            Console.WriteLine("[sim] value load failed: " + e.Message);
        }
    }

    static string ValuesText()
    {
        List<string> parts = new List<string>();
        for (int a = 1; a <= 7; a++)
        {
            for (int r = 0; r < 16; r++)
            {
                if (regs[a, r] != 0) parts.Add(a + ":" + r + "=" + regs[a, r]);
            }
        }
        return string.Join(" ", parts.ToArray());
    }

    static void SendException(SerialPort sp, byte addr, byte fc, byte code)
    {
        byte[] f = new byte[5];
        f[0] = addr;
        f[1] = fc;
        f[2] = code;
        ushort c = Crc(f, 3);
        f[3] = (byte)(c & 0xFF);
        f[4] = (byte)(c >> 8);
        sp.Write(f, 0, f.Length);
    }

    static void HandleFrame(SerialPort sp, byte[] f, ref int served, ref int bad)
    {
        ushort crc = Crc(f, f.Length - 2);
        ushort got = (ushort)(f[f.Length - 2] | (f[f.Length - 1] << 8));
        if (crc != got)
        {
            bad++;
            if (bad <= 5) Console.WriteLine("[sim] crc mismatch on request");
            return;
        }

        byte addr = f[0];
        byte fc = f[1];
        int start = (f[2] << 8) | f[3];
        int qty = (f[4] << 8) | f[5];

        // Unmodelled addresses stay silent, exactly like an absent device.
        if (addr < 1 || addr > 7) return;
        if (fc != 3) return;
        if (qty < 1 || start < 0 || start + qty > 16)
        {
            SendException(sp, addr, (byte)(fc | 0x80), 2);
            return;
        }

        int n = 3 + qty * 2;
        byte[] outb = new byte[n + 2];
        outb[0] = addr;
        outb[1] = fc;
        outb[2] = (byte)(qty * 2);
        for (int i = 0; i < qty; i++)
        {
            ushort v = regs[addr, start + i];
            outb[3 + i * 2] = (byte)(v & 0xFF);
            outb[4 + i * 2] = (byte)(v >> 8);
        }
        ushort rc = Crc(outb, n);
        outb[n] = (byte)(rc & 0xFF);
        outb[n + 1] = (byte)(rc >> 8);

        sp.Write(outb, 0, outb.Length);
        served++;

        if (served <= 12 || served % 200 == 0)
        {
            Console.WriteLine("[sim] #" + served + " slave=" + addr + " reg=" + start +
                              " qty=" + qty + " -> " + regs[addr, start]);
        }
    }

    public static void Run(string portName, int baud, string file)
    {
        valueFile = file;
        if (!File.Exists(valueFile))
        {
            Directory.CreateDirectory(Path.GetDirectoryName(valueFile));
            File.WriteAllText(valueFile, "# <slave>:<reg>=<value>" + Environment.NewLine);
        }
        LoadValues();

        SerialPort sp = new SerialPort(portName, baud, Parity.None, 8, StopBits.One);
        sp.ReadTimeout = 5;
        sp.WriteTimeout = 500;
        sp.ReadBufferSize = 4096;
        sp.Open();
        Console.WriteLine("[sim] " + portName + " open @" + baud +
                          " 8N1; answering only, never requesting");
        Console.Out.Flush();

        List<byte> buf = new List<byte>();
        byte[] chunk = new byte[512];
        int served = 0;
        int bad = 0;
        DateTime lastByte = DateTime.Now;
        DateTime lastBeat = DateTime.Now;

        while (true)
        {
            int avail = sp.BytesToRead;
            if (avail > 0)
            {
                if (avail > chunk.Length) avail = chunk.Length;
                int n = sp.Read(chunk, 0, avail);
                for (int i = 0; i < n; i++) buf.Add(chunk[i]);
                lastByte = DateTime.Now;

                while (buf.Count >= 8)
                {
                    // A request is 8 bytes (FC3/FC4) on this bus; longer frames
                    // are not modelled, so take the first 8.
                    byte[] frame = buf.GetRange(0, 8).ToArray();
                    buf.RemoveRange(0, 8);
                    HandleFrame(sp, frame, ref served, ref bad);
                }
            }
            else
            {
                // Frame boundary is idle time, not a per-byte read timeout: a
                // partial frame that stops mid-way is line noise.
                if (buf.Count > 0 &&
                    (DateTime.Now - lastByte).TotalMilliseconds > 50)
                {
                    buf.Clear();
                }

                Thread.Sleep(1);

                if ((DateTime.Now - lastBeat).TotalSeconds >= 15)
                {
                    Console.WriteLine("[sim] alive served=" + served + " bad=" + bad);
                    Console.Out.Flush();
                    lastBeat = DateTime.Now;
                    LoadValues();
                }
            }
        }
    }
}

