# Free COM4 by ending leftover simulator processes from earlier attempts.
# Only processes whose command line names vg_slave_sim are touched.

$ErrorActionPreference = "Continue"

foreach ($procId in @(26136, 31544)) {
    $p = Get-CimInstance Win32_Process -Filter "ProcessId=$procId" -ErrorAction SilentlyContinue
    if ($null -eq $p) {
        Write-Output ("pid $procId : already gone")
        continue
    }
    Write-Output ("pid $procId : " + $p.Name)
    if ($p.CommandLine -and $p.CommandLine -notmatch 'vg_slave_sim') {
        Write-Output ("pid $procId : not a simulator, leaving it alone")
        continue
    }
    try {
        Stop-Process -Id $procId -Force -ErrorAction Stop
        Write-Output ("pid $procId : killed")
    }
    catch {
        Write-Output ("pid $procId : kill failed - " + $_.Exception.Message)
    }
}

Start-Sleep -Seconds 4

$still = Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -match 'vg_slave_sim\.(ps1|exe)' }
if ($still) {
    Write-Output "simulator processes still present:"
    $still | ForEach-Object { Write-Output ("  " + $_.ProcessId + " " + $_.Name) }
}
else {
    Write-Output "no simulator processes left"
}

try {
    $sp = New-Object System.IO.Ports.SerialPort 'COM4', 9600, 'None', 8, 'One'
    $sp.Open()
    Write-Output "COM4 OPEN OK"
    $sp.Close()
}
catch {
    Write-Output ("COM4 FAIL: " + $_.Exception.Message)
}

# Diagnose who is holding COM4.
# Lists candidate holder processes and reports whether the port frees up.

$ErrorActionPreference = "Continue"

Write-Output "=== COM4 device ==="
Get-PnpDevice -Class Ports | Where-Object { $_.FriendlyName -match 'COM4' } |
    Select-Object Status, FriendlyName, InstanceId | Format-List

Write-Output "=== processes started today that mention a simulator or a slave tool ==="
Get-CimInstance Win32_Process |
    Where-Object {
        $_.CommandLine -and (
            $_.CommandLine -match 'vg_slave_sim' -or
            $_.CommandLine -match 'Modbus' -or
            $_.CommandLine -match 'mthings' -or
            $_.CommandLine -match 'Mbslave'
        )
    } |
    ForEach-Object {
        Write-Output ("pid=" + $_.ProcessId + " name=" + $_.Name + " start=" + $_.CreationDate)
    }

Write-Output "=== port open attempt ==="
foreach ($attempt in 1..3) {
    try {
        $sp = New-Object System.IO.Ports.SerialPort 'COM4', 9600, 'None', 8, 'One'
        $sp.Open()
        Write-Output ("attempt $attempt : COM4 OPEN OK")
        $sp.Close()
        break
    }
    catch {
        Write-Output ("attempt $attempt : busy")
        Start-Sleep -Seconds 3
    }
}

# Force-terminate the leftover simulator process that is holding COM4.
# WMI Terminate succeeds where Stop-Process can report success and leave the
# process blocked in an unmanaged serial read.

$ErrorActionPreference = "Continue"

$targets = Get-CimInstance Win32_Process |
    Where-Object { $_.CommandLine -and $_.CommandLine -match 'vg_slave_sim' }

if (-not $targets) {
    Write-Output "nothing to terminate"
}
else {
    foreach ($t in $targets) {
        Write-Output ("terminating pid=" + $t.ProcessId + " (" + $t.Name + ")")
        try {
            $res = Invoke-CimMethod -InputObject $t -MethodName Terminate
            Write-Output ("  wmi result: " + $res.ReturnValue)
        }
        catch {
            Write-Output ("  wmi failed: " + $_.Exception.Message)
        }
    }
}

Start-Sleep -Seconds 5

$left = Get-CimInstance Win32_Process |
    Where-Object { $_.CommandLine -and $_.CommandLine -match 'vg_slave_sim' }
if ($left) {
    Write-Output "still present:"
    $left | ForEach-Object { Write-Output ("  pid=" + $_.ProcessId) }
}
else {
    Write-Output "clean"
}

foreach ($attempt in 1..4) {
    try {
        $sp = New-Object System.IO.Ports.SerialPort 'COM4', 9600, 'None', 8, 'One'
        $sp.Open()
        Write-Output ("COM4 OPEN OK on attempt " + $attempt)
        $sp.Close()
        break
    }
    catch {
        Write-Output ("attempt " + $attempt + " busy")
        Start-Sleep -Seconds 3
    }
}

