static int next_line(const char **cur, const char *end,
                     const char **ls, size_t *llen)
{
  const char *p = *cur;
  const char *nl;

  if (p >= end)
    {
      return 1;
    }

  nl = memchr(p, '\n', (size_t)(end - p));
  if (nl == NULL)
    {
      *ls = p;
      *llen = (size_t)(end - p);
      *cur = end;
      return 0;
    }

  *ls = p;
  *llen = (size_t)(nl - p);
  *cur = nl + 1;
  return 0;
}

