#
# pnputil /restart-device reported 3010 (ERROR_SUCCESS_REBOOT_REQUIRED), so it
# did not actually re-enumerate the device and the trapped handle survived.
# A disable/enable cycle is a bigger hammer: it tears the device down and
# builds it again, which invalidates outstanding handles without a reboot.
#
# Logs to C:\Users\Public\vg_com4_elevated2.log

$log = "C:\Users\Public\vg_com4_elevated2.log"
function Say([string]$s) { $s | Out-File -LiteralPath $log -Append -Encoding UTF8 }

"=== COM4 recovery attempt 2 " + (Get-Date -Format "yyyy-MM-dd HH:mm:ss") + " ===" |
    Out-File -LiteralPath $log -Encoding UTF8

$inst = "USB\VID_345F&PID_3020\A02001FJ"
$holder = 26136

Say ("admin: " + ([Security.Principal.WindowsPrincipal] `
    [Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole(
