using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO.Ports;
using System.Runtime.InteropServices;

// Cancel the synchronous I/O that has the trapped reader thread parked in the
// USB-serial driver.  A thread sitting in an uncancellable-looking
// Wait/Executive wait is often just a blocking ReadFile on a comm handle:
// CancelSynchronousIo makes that ReadFile return ERROR_OPERATION_ABORTED, the
// managed SerialPort raises, its loop unwinds, and the process can finally
// exit and release the port.
public class VgCancelIo
{
    const uint THREAD_TERMINATE = 0x0001;
    const uint THREAD_SUSPEND_RESUME = 0x0002;
    const uint THREAD_QUERY_INFORMATION = 0x0040;

    [DllImport("kernel32.dll", SetLastError = true)]
    static extern IntPtr OpenThread(uint access, bool inherit, uint threadId);

    [DllImport("kernel32.dll", SetLastError = true)]
    static extern bool CloseHandle(IntPtr h);

    [DllImport("kernel32.dll", SetLastError = true)]
    static extern bool CancelSynchronousIo(IntPtr hThread);

    [DllImport("kernel32.dll", SetLastError = true)]
    static extern bool TerminateProcess(IntPtr hProcess, uint exitCode);

    [DllImport("kernel32.dll", SetLastError = true)]
    static extern IntPtr OpenProcess(uint access, bool inherit, int pid);

    [DllImport("kernel32.dll", SetLastError = true)]
    static extern uint WaitForSingleObject(IntPtr h, uint ms);

    const uint PROCESS_TERMINATE = 0x0001;
    const uint PROCESS_QUERY_INFORMATION = 0x0400;
    const uint SYNCHRONIZE = 0x00100000;

    static bool PortFree()
    {
        try
        {
            SerialPort sp = new SerialPort("COM4", 9600, Parity.None, 8, StopBits.One);
            sp.Open();
            sp.Close();
            return true;
        }
        catch { return false; }
    }

    public static int Run(int pid)
    {
        Console.WriteLine("port free before: " + PortFree());

        Process p;
        try { p = Process.GetProcessById(pid); }
        catch { Console.WriteLine("pid " + pid + " not found"); return 1; }

        Console.WriteLine("target cpu=" + p.TotalProcessorTime.TotalSeconds.ToString("F3") +
                          " threads=" + p.Threads.Count);

        // 1) Cancel any synchronous I/O outstanding on each thread.
        foreach (ProcessThread t in p.Threads)
        {
            IntPtr h = OpenThread(THREAD_TERMINATE | THREAD_SUSPEND_RESUME |
                                  THREAD_QUERY_INFORMATION, false, (uint)t.Id);
            if (h == IntPtr.Zero)
            {
                Console.WriteLine("thread " + t.Id + ": OpenThread failed err=" +
                                  Marshal.GetLastWin32Error());
                continue;
            }

            bool ok = CancelSynchronousIo(h);
            int err = Marshal.GetLastWin32Error();
            Console.WriteLine("thread " + t.Id + ": CancelSynchronousIo=" + ok +
                              " err=" + err);
            CloseHandle(h);
        }

        System.Threading.Thread.Sleep(1500);

        // 2) Force-terminate at the OS level.
        IntPtr hp = OpenProcess(PROCESS_TERMINATE | PROCESS_QUERY_INFORMATION | SYNCHRONIZE,
                                false, pid);
        if (hp == IntPtr.Zero)
        {
            Console.WriteLine("OpenProcess failed err=" + Marshal.GetLastWin32Error());
        }
        else
        {
            bool ok = TerminateProcess(hp, 1u);
            Console.WriteLine("TerminateProcess=" + ok + " err=" +
                              Marshal.GetLastWin32Error());
            WaitForSingleObject(hp, 5000);
            CloseHandle(hp);
        }

        System.Threading.Thread.Sleep(2000);

        bool alive;
        try { Process.GetProcessById(pid); alive = true; }
        catch { alive = false; }
        Console.WriteLine("alive after: " + alive);

        System.Threading.Thread.Sleep(1000);
        Console.WriteLine("port free after: " + PortFree());
        return 0;
    }
}

public class VgCancelIoMain
{
    static int Main(string[] args)
    {
        int pid = (args.Length > 0) ? int.Parse(args[0]) : 26136;
        return VgCancelIo.Run(pid);
    }
}

# Read-only: walk the device tree above the COM4 adapter and find which hub
# port it hangs off, plus what else shares that parent.
$ErrorActionPreference = "Continue"

$inst = "USB\VID_345F&PID_3020\A02001FJ"

function Show([string]$instance) {
    $d = Get-PnpDevice -InstanceId $instance -ErrorAction SilentlyContinue
    if (-not $d) {
        Write-Output ("  " + $instance + "  (not present)")
        return
    }
    Write-Output ("  [" + $d.Status + "] " + $d.Class + " : " + $d.FriendlyName)
}

Write-Output "=== chain above COM4 ==="
$cur = $inst
for ($i = 0; $i -lt 6; $i++) {
    Show $cur
    $node = Get-PnpDeviceProperty -InstanceId $cur -KeyName 'DEVPKEY_Device_Parent' -ErrorAction SilentlyContinue
    if (-not $node -or -not $node.Data) { break }
    $cur = $node.Data
}

Write-Output ""
Write-Output "=== everything under the immediate parent ==="
$parent = (Get-PnpDeviceProperty -InstanceId $inst -KeyName 'DEVPKEY_Device_Parent' -ErrorAction SilentlyContinue).Data
if ($parent) {
    Write-Output ("parent = " + $parent)
    Get-PnpDevice -ErrorAction SilentlyContinue |
        Where-Object { $_.InstanceId -like "$parent*" -or $_.InstanceId -eq $parent } |
        ForEach-Object { Write-Output ("  [" + $_.Status + "] " + $_.Class + " : " + $_.FriendlyName + "  (" + $_.InstanceId + ")") }

    # Siblings: devices whose parent is the same node.
    Write-Output ""
    Write-Output "=== siblings (same parent) ==="
    Get-PnpDevice -ErrorAction SilentlyContinue | ForEach-Object {
        $pp = (Get-PnpDeviceProperty -InstanceId $_.InstanceId -KeyName 'DEVPKEY_Device_Parent' -ErrorAction SilentlyContinue).Data
        if ($pp -eq $parent) {
            Write-Output ("  [" + $_.Status + "] " + $_.Class + " : " + $_.FriendlyName)
        }
    }
}

