        }
    }

  /* An existing leaf directory is success, not failure.  Callers use the
   * return value to tell "cannot create" apart from "already there"; the
   * raw mkdir() result cannot express that.
   */

  if (mkdir(tmp, 0755) != 0 && errno != EEXIST)
    {
      return -errno;
    }

  return 0;
}

