# Rebuild the VelaGuard candidate point table over NSH, test-read it, and STOP.
#
# This never touches the committed table: it only writes the candidate and runs
# the read-only test.  The final "vgpoint apply --confirm" is left to a human,
# per the project rule that edit/test/apply are three separate steps.
param(
  [string]$ComPort = "COM3",
  [int]$Baud = 115200,
  [string]$PointsFile = "C:\Users\Public\vg_restore_points.json",
  [switch]$SkipTest
)

$ErrorActionPreference = "Stop"

$points = @((Get-Content -Raw -Encoding UTF8 $PointsFile | ConvertFrom-Json).points)
if ($points.Count -lt 1) { throw "no points in $PointsFile" }

function Build-AddCmd($pt) {
  $cmd = "vgpoint add -i $($pt.id) -a $([int]$pt.addr) -r $([int]$pt.reg)"
  if ($null -ne $pt.fc)     { $cmd += " -f $([int]$pt.fc)" }
  if ($null -ne $pt.qty)    { $cmd += " -q $([int]$pt.qty)" }
  if ("$($pt.dtype)" -ne "") { $cmd += " -d $($pt.dtype)" }
  if ($null -ne $pt.scale)  { $cmd += " -s $($pt.scale)" }
  if ("$($pt.unit)" -ne "") { $cmd += " -u $($pt.unit)" }
  if ("$($pt.cmp)" -ne "")  { $cmd += " -k $($pt.cmp)" }
  if ($null -ne $pt.warn)   { $cmd += " -w $($pt.warn)" }
  if ($null -ne $pt.crit)   { $cmd += " -C $($pt.crit)" }
  if ($null -ne $pt.fail_n) { $cmd += " -n $([int]$pt.fail_n)" }
  if ("$($pt.name)" -ne "") { $cmd += " -N $($pt.name)" }
  if ([System.Text.Encoding]::UTF8.GetByteCount($cmd) -gt 120) {
    throw "command longer than 120 bytes: $cmd"
  }
  return $cmd
}

$port = New-Object System.IO.Ports.SerialPort $ComPort, $Baud, 'None', 8, 'One'
$port.Encoding = [System.Text.Encoding]::UTF8
$port.ReadTimeout = 3000
$port.NewLine = "`r"
$port.DtrEnable = $true
$port.RtsEnable = $true

function Drain([int]$ms) {
  $b = ""
  $dl = (Get-Date).AddMilliseconds($ms)
  while ((Get-Date) -lt $dl) {
    if ($port.BytesToRead -gt 0) { $b += $port.ReadExisting() }
    Start-Sleep -Milliseconds 60
  }
  return $b
}

function Send([string]$c, [int]$waitMs = 2500) {
  $port.DiscardInBuffer()
  $port.Write("$c`r")
  Start-Sleep -Milliseconds 400
  $o = Drain $waitMs
  Write-Output "########## $c ##########"
  Write-Output $o
  return $o
}

$script:okCount = 0
$script:failCount = 0

try {
  $port.Open()
  Start-Sleep -Milliseconds 900
  [void](Drain 2500)

  Write-Output "===== store writability probe (config/ and reports/) ====="
  [void](Send "dd if=/dev/zero of=/data/velaguard/config/.wtest count=1 bs=64" 1500)
  [void](Send "dd if=/dev/zero of=/data/velaguard/reports/.wtest count=1 bs=64" 1500)
  [void](Send "ls /data/velaguard/config" 1500)
  [void](Send "ls /data/velaguard/reports" 1500)
  [void](Send "rm /data/velaguard/config/.wtest" 1200)
  [void](Send "rm /data/velaguard/reports/.wtest" 1200)

  Write-Output "===== clear any stale candidate, then rebuild ====="
  [void](Send "vgpoint abort" 1500)

  foreach ($pt in $points) {
    $c = Build-AddCmd $pt
    $o = Send $c 2500
    if ($o -match "vgpoint: OK cmd=add") {
      $script:okCount++
      Write-Output "[OK]   add $($pt.id)"
    } elseif ($o -match "code=dup_id") {
      $set = $c -replace "^vgpoint add -i $($pt.id) ", "vgpoint set $($pt.id) "
      $o2 = Send $set 2500
      if ($o2 -match "vgpoint: OK cmd=set") {
        $script:okCount++
        Write-Output "[OK]   set $($pt.id) (already present)"
      } else {
        $script:failCount++
        Write-Output "[FAIL] set $($pt.id)"
      }
    } else {
      $script:failCount++
      Write-Output "[FAIL] add $($pt.id)"
    }
  }

  Write-Output "===== candidate table ====="
  [void](Send "vgpoint list -c" 3000)

  if (-not $SkipTest) {
    Write-Output "===== test read (needs live slaves on RS485) ====="
    [void](Send "vgpoint test" 45000)
  }

  Write-Output ""
  Write-Output "[restore] candidate ok=$($script:okCount) fail=$($script:failCount) / $($points.Count)"
  Write-Output "[restore] STOPPED before apply. Committed table unchanged."
  Write-Output "[restore] Human step: review the READ lines, then run"
  Write-Output "[restore]   vgpoint apply --confirm"
} catch {
  Write-Output ("ERROR: " + $_.Exception.Message)
} finally {
  if ($port.IsOpen) { $port.Close() }
}

param([string]$ComPort = "COM3", [int]$Baud = 115200)
$ErrorActionPreference = "Continue"
$cmds = @(
  'dd if=/dev/zero of=/data/velaguard/config/.wtest count=1 bs=64',
  'ls /data/velaguard/config',
  'dd if=/dev/zero of=/data/velaguard/reports/.wtest count=1 bs=64',
  'ls /data/velaguard/reports',
  'rm /data/velaguard/config/.wtest',
  'rm /data/velaguard/reports/.wtest',
  'ls /data/velaguard/config',
  'ls /data/velaguard/reports',
  'ls -l /data/velaguard/config'
)
$port = New-Object System.IO.Ports.SerialPort $ComPort, $Baud, 'None', 8, 'One'
$port.Encoding = [System.Text.Encoding]::ASCII
$port.ReadTimeout = 3000
$port.DtrEnable = $true; $port.RtsEnable = $true
function Drain([int]$ms) {
  $b = ""; $dl = (Get-Date).AddMilliseconds($ms)
  while ((Get-Date) -lt $dl) { if ($port.BytesToRead -gt 0) { $b += $port.ReadExisting() }; Start-Sleep -Milliseconds 60 }
  return $b
}
try {
  $port.Open(); Start-Sleep -Milliseconds 800; [void](Drain 2500)
  foreach ($c in $cmds) {
    $port.DiscardInBuffer(); $port.Write("$c`r"); Start-Sleep -Milliseconds 500
    Write-Output "##### $c"
    Write-Output (Drain 3500)
  }
} catch { Write-Output ("PORT ERROR: " + $_.Exception.Message) } finally { if ($port.IsOpen) { $port.Close() } }

