    static void HandleFrame(SerialPort sp, byte[] f, ref int served, ref int bad)
    {
        ushort crc = Crc(f, f.Length - 2);
        ushort got = (ushort)(f[f.Length - 2] | (f[f.Length - 1] << 8));
        if (crc != got)
        {
            bad++;
            if (bad <= 5) Console.WriteLine("[sim] crc mismatch on request");
            return;
        }

        byte addr = f[0];
        byte fc = f[1];
        int start = (f[2] << 8) | f[3];
        int qty = (f[4] << 8) | f[5];

        // Unmodelled addresses stay silent, exactly like an absent device.
        if (addr < 1 || addr > 7) return;
        if (fc != 3) return;
        if (qty < 1 || start < 0 || start + qty > 16)
        {
            SendException(sp, addr, (byte)(fc | 0x80), 2);
            return;
        }

        int n = 3 + qty * 2;
        byte[] outb = new byte[n + 2];
        outb[0] = addr;
        outb[1] = fc;
        outb[2] = (byte)(qty * 2);
        for (int i = 0; i < qty; i++)
        {
            ushort v = regs[addr, start + i];
            outb[3 + i * 2] = (byte)(v & 0xFF);
            outb[4 + i * 2] = (byte)(v >> 8);
        }
        ushort rc = Crc(outb, n);
        outb[n] = (byte)(rc & 0xFF);
        outb[n + 1] = (byte)(rc >> 8);

        sp.Write(outb, 0, outb.Length);
        served++;

        if (served <= 12 || served % 200 == 0)
        {
            Console.WriteLine("[sim] #" + served + " slave=" + addr + " reg=" + start +
                              " qty=" + qty + " -> " + regs[addr, start]);
        }
    }

