param([string]$ComPort = "COM3", [int]$Baud = 115200)
$ErrorActionPreference = "Continue"
$cmds = @(
  'config_show',
  'router_status',
  'exit'
)
$port = New-Object System.IO.Ports.SerialPort $ComPort, $Baud, 'None', 8, 'One'
$port.Encoding = [System.Text.Encoding]::ASCII
$port.ReadTimeout = 3000
$port.DtrEnable = $true; $port.RtsEnable = $true
function Drain([int]$ms) {
  $b = ""; $dl = (Get-Date).AddMilliseconds($ms)
  while ((Get-Date) -lt $dl) { if ($port.BytesToRead -gt 0) { $b += $port.ReadExisting() }; Start-Sleep -Milliseconds 60 }
  return $b
}
try {
  $port.Open(); Start-Sleep -Milliseconds 900; [void](Drain 3000)
  foreach ($c in $cmds) {
    $port.DiscardInBuffer(); $port.Write("$c`r"); Start-Sleep -Milliseconds 600
    Write-Output "##### $c"
    Write-Output (Drain 6000)
  }
} catch { Write-Output ("PORT ERROR: " + $_.Exception.Message) } finally { if ($port.IsOpen) { $port.Close() } }

